    await waitForSomeRequestsToAppear(devToolsPage, 2);

    const name = await devToolsPage.waitForFunction(async () => {
      const names = await getAllRequestNames(devToolsPage);
      const name = names.find(v => v?.startsWith('data:'));
      return name;
    });
